import{describe,it,expect}from"vitest";import{BANKING_TIMELINE_DATA,filterBankingTimeline,getBankingEraBadgeClass,getUPIInfographicData,getPresidencyFlowData}from"../../frontend/history-of-indian-banking/script.js";describe("History of Indian Banking Module",()=>{it("contains a complete dataset covering all major banking historical eras",()=>{expect(Array.isArray(BANKING_TIMELINE_DATA)).toBe(!0),expect(BANKING_TIMELINE_DATA.length).toBeGreaterThanOrEqual(18),BANKING_TIMELINE_DATA.forEach((e,t)=>{expect(e,`Milestone ${t} missing id`).toHaveProperty("id"),expect(e,`Milestone ${t} missing year`).toHaveProperty("year"),expect(e,`Milestone ${t} missing title`).toHaveProperty("title"),expect(e,`Milestone ${t} missing era`).toHaveProperty("era"),expect(e,`Milestone ${t} missing eraId`).toHaveProperty("eraId"),expect(e,`Milestone ${t} missing category`).toHaveProperty("category"),expect(e,`Milestone ${t} missing summary`).toHaveProperty("summary"),expect(e,`Milestone ${t} missing details`).toHaveProperty("details"),expect(e,`Milestone ${t} missing keyImpact`).toHaveProperty("keyImpact"),expect(e,`Milestone ${t} missing facts`).toHaveProperty("facts"),expect(Array.isArray(e.facts)).toBe(!0),expect(e.facts.length).toBeGreaterThan(0)})}),it("covers all 7 required core topics in Indian banking history",()=>{const e=BANKING_TIMELINE_DATA.map(e=>e.title.toLowerCase()),t=BANKING_TIMELINE_DATA.map(e=>e.summary.toLowerCase()+" "+e.details.toLowerCase()),a=e.concat(t).join(" ");expect(a).toContain("presidency"),expect(a).toContain("bank of bengal"),expect(a).toContain("imperial bank"),expect(a).toContain("reserve bank of india"),expect(a).toContain("nationalization"),expect(a).toContain("narasimham"),expect(a).toContain("core banking"),expect(a).toContain("unified payments interface")}),it("filters banking timeline by search keyword query",()=>{const e=filterBankingTimeline(BANKING_TIMELINE_DATA,"UPI");expect(e.length).toBeGreaterThanOrEqual(1),expect(e.some(e=>e.title.includes("Unified Payments Interface"))).toBe(!0);const t=filterBankingTimeline(BANKING_TIMELINE_DATA,"State Bank of India");expect(t.length).toBeGreaterThanOrEqual(1);const a=filterBankingTimeline(BANKING_TIMELINE_DATA,"1969");expect(a.length).toBeGreaterThanOrEqual(1),expect(a[0].year).toBe("1969")}),it("filters banking timeline by era category",()=>{const e=filterBankingTimeline(BANKING_TIMELINE_DATA,"","presidency");expect(e.length).toBeGreaterThanOrEqual(3),e.forEach(e=>expect(e.eraId).toBe("presidency"));const t=filterBankingTimeline(BANKING_TIMELINE_DATA,"","rbi");expect(t.length).toBeGreaterThanOrEqual(3),t.forEach(e=>expect(e.eraId).toBe("rbi"));const a=filterBankingTimeline(BANKING_TIMELINE_DATA,"","upi");expect(a.length).toBeGreaterThanOrEqual(4),a.forEach(e=>expect(e.eraId).toBe("upi"))}),it("returns correct CSS badge class names for banking eras",()=>{expect(getBankingEraBadgeClass("presidency")).toBe("era-presidency"),expect(getBankingEraBadgeClass("imperial")).toBe("era-imperial"),expect(getBankingEraBadgeClass("rbi")).toBe("era-rbi"),expect(getBankingEraBadgeClass("nationalization")).toBe("era-nationalization"),expect(getBankingEraBadgeClass("liberalization")).toBe("era-liberalization"),expect(getBankingEraBadgeClass("digital")).toBe("era-digital"),expect(getBankingEraBadgeClass("upi")).toBe("era-upi"),expect(getBankingEraBadgeClass("other")).toBe("era-default")}),it("returns valid datasets for infographics (Presidency Flow & UPI growth)",()=>{const e=getPresidencyFlowData();expect(Array.isArray(e)).toBe(!0),expect(e.length).toBe(3),expect(e[0].stage).toContain("Presidency Banks Era");const t=getUPIInfographicData();expect(Array.isArray(t)).toBe(!0),expect(t.length).toBeGreaterThanOrEqual(5),expect(t[0]).toHaveProperty("year"),expect(t[0]).toHaveProperty("volume"),expect(t[0]).toHaveProperty("value")})});